from taf.ul.ettf.msg_capture.expectations import ExpectationsManager
from taf.ul.ettf.resources.expectations.utils import rrc_message
from taf.ul.ettf.msg_capture.expectation_builders.detailed import MessageHeader
from taf.ul.ettf.msg_capture.expectation_builders import Unexpected


class rrc_messages(ExpectationsManager):
    def expect_rrc_connection_setup(self):
        self.append_expectation(MessageHeader(*rrc_message('rrcConnectionSetup')))

    def expect_rrc_connection_reconfiguration(self):
        self.append_expectation(MessageHeader(*rrc_message('rrcConnectionReconfiguration')))

    def expect_no_rrc_connection_reconfiguration(self):
        self.append_expectation(MessageHeader(*rrc_message('rrcConnectionReconfiguration'), policy=Unexpected))

    def expect_rrc_connection_release(self):
        self.append_expectation(MessageHeader(*rrc_message('rrcConnectionRelease')))

    def expect_system_information_block_1(self):
        self.append_expectation(MessageHeader(*rrc_message('systemInformationBlockType1')))
